    }

    @Override
    public void propertyChange(Preferences.PropertyChangeEvent event) {
        System.out.println("Property changed: " + event.getProperty() + " -> " + event.getNewValue());
    }

    public void anotherMethod() {
        preferences.setValue("test", true);
